toolCall.source:
export default async function run(ctx, host) {
  const c = ctx.config;
  const url = `${c.baseUrl}?latitude=${c.latitude}&longitude=${c.longitude}&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=${encodeURIComponent(ctx.timezone)}&forecast_days=1`;
  const json = await host.fetchJson(url);
  return {
    kind: "data",
    data: {
      maxC: json.daily.temperature_2m_max[0],
      minC: json.daily.temperature_2m_min[0],
      rainChancePercent: json.daily.precipitation_probability_max[0],
    },
  };
}
